from math import gcd
obs={9:1,28:5,36:3,50:3,52:4}
valid=[]
for p in range(1,31):
    m={}
    ok=True
    for s,c in obs.items():
        r=s%p
        if r in m and m[r]!=c:
            ok=False; break
        m[r]=c
    if ok: valid.append((p,len(m),p-len(m),m))
print(valid)

from itertools import combinations
marks={9:1,28:5,36:3,50:3,52:4}
valid=[]
for p in range(1,28):
    residues={}
    conflict=[]
    for s,c in marks.items():
        r=s%p
        if r in residues and residues[r]!=c:
            conflict.append((r,residues[r],c))
        residues[r]=c
    if not conflict: valid.append((p, sorted(residues.items()), p-len(residues)))
print('consistent periods 1..27:')
for x in valid: print(x)
for p in (7,14):
    mapping={}
    for s,c in marks.items(): mapping[s%p]=c
    print('p',p,'assignments',sorted(mapping.items()),'unknown', [r for r in range(p) if r not in mapping])
    print('line colors at sums 0..54 if unknown=.?')
    print(' '.join(str(mapping.get(s%p,'.')) for s in range(55)))

